            "<span style=\"color:#E1E4E8\">&lt;?</span><span style=\"color:#85E89D\">xml</span><span style=\"color:#B392F0\"> version</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">'1.0'</span><span style=\"color:#B392F0\"> encoding</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">'utf-8'</span><span style=\"color:#E1E4E8\">?&gt;</span>",
            "<span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#85E89D\">resources</span><span style=\"color:#E1E4E8\">&gt;</span>",
            "<span style=\"color:#E1E4E8\">    &lt;</span><span style=\"color:#85E89D\">string</span><span style=\"color:#B392F0\"> name</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"app_name\"</span><span style=\"color:#E1E4E8\">&gt;capacitor-stripe&lt;/</span><span style=\"color:#85E89D\">string</span><span style=\"color:#E1E4E8\">&gt;</span>",
            "<span style=\"color:#E1E4E8\">    &lt;</span><span style=\"color:#85E89D\">string</span><span style=\"color:#B392F0\"> name</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"title_activity_main\"</span><span style=\"color:#E1E4E8\">&gt;capacitor-stripe&lt;/</span><span style=\"color:#85E89D\">string</span><span style=\"color:#E1E4E8\">&gt;</span>",
            "<span style=\"color:#E1E4E8\">    &lt;</span><span style=\"color:#85E89D\">string</span><span style=\"color:#B392F0\"> name</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"package_name\"</span><span style=\"color:#E1E4E8\">&gt;io.ionic.starter&lt;/</span><span style=\"color:#85E89D\">string</span><span style=\"color:#E1E4E8\">&gt;</span>",
            "<span style=\"color:#E1E4E8\">    &lt;</span><span style=\"color:#85E89D\">string</span><span style=\"color:#B392F0\"> name</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"custom_url_scheme\"</span><span style=\"color:#E1E4E8\">&gt;io.ionic.starter&lt;/</span><span style=\"color:#85E89D\">string</span><span style=\"color:#E1E4E8\">&gt;</span>",
            "",
            "<span style=\"color:#E1E4E8\">    &lt;</span><span style=\"color:#85E89D\">string</span><span style=\"color:#B392F0\"> name</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"publishable_key\"</span><span style=\"color:#E1E4E8\">&gt;Your Publishable Key&lt;/</span><span style=\"color:#85E89D\">string</span><span style=\"color:#E1E4E8\">&gt;</span>",
            "<span style=\"color:#E1E4E8\">    &lt;</span><span style=\"color:#85E89D\">bool</span><span style=\"color:#B392F0\"> name</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"enable_google_pay\"</span><span style=\"color:#E1E4E8\">&gt;true&lt;/</span><span style=\"color:#85E89D\">bool</span><span style=\"color:#E1E4E8\">&gt;</span>",
            "<span style=\"color:#E1E4E8\">    &lt;</span><span style=\"color:#85E89D\">string</span><span style=\"color:#B392F0\"> name</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"country_code\"</span><span style=\"color:#E1E4E8\">&gt;US&lt;/</span><span style=\"color:#85E89D\">string</span><span style=\"color:#E1E4E8\">&gt;</span>",
            "<span style=\"color:#E1E4E8\">    &lt;</span><span style=\"color:#85E89D\">string</span><span style=\"color:#B392F0\"> name</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"merchant_display_name\"</span><span style=\"color:#E1E4E8\">&gt;Widget Store&lt;/</span><span style=\"color:#85E89D\">string</span><span style=\"color:#E1E4E8\">&gt;</span>",
